window.OFW_V14_BUSINESS_DEFINITIONS={"definitions":[{"id":"balance","name":"存续融资余额","unit":"百万元","expression":"Σ 当期存续借款本金 (Loan ID 唯一去重)","inputs":["loan.principal","loan.startDate","loan.maturityDate"],"consumers":["地图","问数","方案","报告"],"scope":"起息日不晚于观察日、到期日晚于观察日的人民币借款；未用授信和担保不重复计入"},{"id":"weightedCost","name":"余额加权融资成本","unit":"%","expression":"Σ(存续本金 × 执行年利率) / Σ存续本金","inputs":["loan.principal","loan.rate"],"consumers":["地图","问数","方案","报告"],"scope":"当期存续、同币种借款；按本金加权，不取企业利率简单平均"},{"id":"maturity","name":"窗口内到期本金","unit":"百万元","expression":"Σ 到期日 > 观察日 且 ≤ 观察日 + 展望天数 的存续本金","inputs":["loan.principal","loan.maturityDate"],"consumers":["地图","问数","方案","报告"],"scope":"不含已逾期借款；窗口末日包含；本金不重复计入担保额"},{"id":"gap","name":"偿债资金缺口","unit":"百万元","expression":"max(0, 窗口到期本金 − 可用现金 − 窗口有效未用授信)","inputs":["maturity","enterprise.cash","facility.undrawn","facility.validUntil"],"consumers":["地图","问数","方案","报告"],"scope":"演示确定性测算；未用授信不等于已到账资金；不包含经营现金流预测"},{"id":"exposure","name":"银行借款敞口","unit":"百万元","expression":"Σ 当前对象集在所选银行的存续借款本金","inputs":["loan.bankId","loan.principal"],"consumers":["地图","问数","方案"],"scope":"按唯一 Loan ID 去重；贷款和授信不相加，不叠加担保金额"},{"id":"riskScore","name":"历史债务风险评分","unit":"分","expression":"直接引用现行 1.0.2 模型历史评分","inputs":["riskSource"],"consumers":["地图","问数","报告"],"scope":"分数越低越需关注；不在方案中重算，不与成本拼成综合分"},{"id":"costPremium","name":"融资成本偏离","unit":"bp","expression":"(企业加权成本 − 同产业演示基准利率) × 100","inputs":["weightedCost","enterprise.benchmarkRate"],"consumers":["地图","问数","方案"],"scope":"产业基准为明示演示参数，非市场报价；未做期限与信用评级匹配"}],"digest":"6594b6e72a6cc1a636766591e3a80675f5304247641645fb5893ea3232fe7613","dataVersion":"DATA-V14-20251231-DEMO-1","ontologyVersion":"ONT-ENTERPRISE-FINANCE-RISK-1.4","asOf":"2025-12-31"};
